xpath.script:
//
(function () {
    'use strict';

    function clearOdoo() {
        ['wrapwrap', 'wrap'].forEach(function (id) {
            var el = document.getElementById(id);
            if (!el) return;
            ['opacity','visibility','transition','transform'].forEach(function (p) {
                el.style.removeProperty(p);
            });
        });
    }

    function buildStars() {
        var field = document.getElementById('hs-stars-field');
        if (!field) return;
        field.innerHTML = '';
        var frag = document.createDocumentFragment();
        for (var i = 0; i < 90; i++) {
            var s  = document.createElement('div');
            var sz = (Math.random() * 2.5 + 0.5).toFixed(1);
            s.className = 'hs-star';
            s.style.cssText = [
                'width:'    + sz + 'px',
                'height:'   + sz + 'px',
                'top:'      + (Math.random() * 100).toFixed(2) + '%',
                'left:'     + (Math.random() * 100).toFixed(2) + '%',
                '--dur:'    + (Math.random() * 3 + 2).toFixed(1) + 's',
                '--delay:-' + (Math.random() * 4).toFixed(1) + 's'
            ].join(';');
            frag.appendChild(s);
        }
        field.appendChild(frag);
    }

    function resetScroll() {
        window.scrollTo(0, 0);
        document.documentElement.scrollTop = 0;
        document.body.scrollTop = 0;
        var ww = document.getElementById('wrapwrap');
        if (ww) ww.scrollTop = 0;
    }

    /* Las estrellas solo se generan una vez */
    var starsBuilt = false;

    function init() {
        clearOdoo();
        resetScroll();
        if (!starsBuilt) {
            buildStars();
            starsBuilt = true;
        }
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
    window.addEventListener('load', function () { setTimeout(init, 30); });
    window.addEventListener('resize', clearOdoo);

    ['pushState','replaceState'].forEach(function (m) {
        var orig = history[m].bind(history);
        history[m] = function () {
            orig.apply(this, arguments);
            starsBuilt = false; /* Permitir regenerar si se vuelve a la 404 */
            setTimeout(init, 60);
        };
    });
    window.addEventListener('popstate', function () {
        starsBuilt = false;
        setTimeout(init, 60);
    });

    /* Vigilar cambios de style en wrapwrap */
    var ww = document.getElementById('wrapwrap');
    if (ww) {
        new MutationObserver(function (mutations) {
            mutations.forEach(function (m) {
                if (m.attributeName === 'style') clearOdoo();
            });
        }).observe(ww, { attributes: true });
    }

})();
//
